function SavePaymentRec(ADatePayment: TDateTime;
  const AText: string; AValue: double;
  const AAccount: string='';
  const ABank: string='';
  const ASpecSym: string='';
  const AVarSym: string='';
  const AKonSym: string='';
  const AIBAN: string='';
  const ASwift: string=''): boolean;
  var iban, bu: string;
begin
  if (GfaMain.FLocalVersion = cLocalVersionSK) and (AIBAN='') then begin
    bu:=AAccount+'/'+ABank;
    iban:=ConvertBU2IBAN(bu,'SK');
  end
  else
    iban:=AIBAN;
{$IFDEF STANDALONE}
  MessageInfo('Payment info',
    'Text: '+Atext+#13#10+
    'Value: '+ FloatToStr(AValue)+#13#10+
    'Account: '+AAccount+#13#10+
    'Bank: '+ABank+#13#10+
    'SpecSym: '+ASpecSym+#13#10+
    'VarSym: '+AVarSym+#13#10+
    'KonSym: '+AKonSym+#13#10+
    'IBAN: '+iban+#13#10+
    'Swift: '+ASwift, [MBOK]);
  Result := TRUE;
{$ELSE STANDALONE}
  Result := SavePaymentInfo(GfaMain.FClientID, ADatePayment, AText, AValue,
    AAccount, ABank, ASpecSym, AVarSym, AKonSym, iban, ASwift,
